// Cloudflare API Helper
// Shared utilities for all Cloudflare models
// Auto-generated by scripts/cloudflare-codegen — do not edit manually.

const CF_API_BASE = "https://api.cloudflare.com/client/v4";

/**
 * Resolve the Cloudflare API token from the apiToken global argument, which
 * should be wired with a vault.get expression. The CLOUDFLARE_API_TOKEN
 * environment variable is read as a fallback only; swamp does not redact it,
 * so it is not recommended. Throws a descriptive error when neither is set.
 */
function resolveToken(apiToken?: string): string {
  const token = apiToken || Deno.env.get("CLOUDFLARE_API_TOKEN");
  if (!token) {
    throw new Error(
      "Cloudflare API token not set. Store the token in a vault and set the " +
        "apiToken global argument to " +
        '${{ vault.get("cloudflare", "API_TOKEN") }}. ' +
        "The CLOUDFLARE_API_TOKEN environment variable is read as a fallback, " +
        "but it is not redacted and is not recommended.",
    );
  }
  return token;
}

/**
 * One step of a path to a returned secret: a property (optionally only when a
 * sibling discriminator matches), every array element, or every map value.
 */
export interface SensitivePathSegment {
  k?: string;
  when?: readonly unknown[];
  each?: boolean;
  values?: boolean;
}

/**
 * Return a copy of `value` with the secret at every path removed.
 *
 * Swamp moves a resource field marked sensitive into a vault, but only along
 * plain object properties. Secrets inside list items, maps or unions cannot be
 * vaulted, so the generated methods delete them before writing the resource
 * rather than persist them in plaintext.
 */
export function stripSensitive<T>(
  value: T,
  paths: ReadonlyArray<ReadonlyArray<SensitivePathSegment>>,
): T {
  if (value === null || typeof value !== "object") return value;
  const copy = structuredClone(value);
  for (const path of paths) removePath(copy, path, 0);
  return copy;
}

function removePath(
  node: unknown,
  path: ReadonlyArray<SensitivePathSegment>,
  i: number,
): void {
  if (node === null || typeof node !== "object" || i >= path.length) return;
  const seg = path[i];
  if (seg.each) {
    if (Array.isArray(node)) {
      for (const el of node) removePath(el, path, i + 1);
    }
    return;
  }
  if (Array.isArray(node)) return;
  const obj = node as Record<string, unknown>;
  if (seg.values) {
    for (const v of Object.values(obj)) removePath(v, path, i + 1);
    return;
  }
  if (seg.k === undefined) return;
  if (seg.when && obj[String(seg.when[0])] !== seg.when[1]) return;
  if (i === path.length - 1) {
    delete obj[seg.k];
  } else {
    removePath(obj[seg.k], path, i + 1);
  }
}

export interface CloudflareResponse<T> {
  success: boolean;
  errors: Array<{ code: number; message: string }>;
  messages: string[];
  result: T;
  result_info?: {
    page: number;
    per_page: number;
    total_count: number;
    total_pages: number;
    cursor?: string;
  };
}

/**
 * Sanitize a resource instance name for swamp's data layer.
 *
 * Swamp rejects data-artifact instance names containing "/", "\", "..", or
 * null bytes (path-traversal protection). Instance names are frequently derived
 * from API-returned identifiers, which are attacker-influenceable, so every
 * writeResource instance name is routed through this before it reaches the
 * datastore.
 */
export function sanitizeInstanceName(name: string): string {
  return name
    .replace(/[/\\]/g, "_")
    .replace(/\.\./g, "_")
    .replace(/\0/g, "");
}

/**
 * Deterministic short hash (SHA-1, first 16 hex characters) for a resource
 * instance name that no response field supplies, so distinct calls never
 * share one instance.
 */
export async function shortHash(input: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-1",
    new TextEncoder().encode(input),
  );
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
    .slice(0, 16);
}

const MAX_RETRIES = 3;

/**
 * Perform a fetch with bounded retry on HTTP 429. Honors the `Retry-After`
 * header when present (seconds), otherwise backs off linearly. Returns the
 * final Response for the caller to inspect; does not throw on non-429 statuses.
 */
async function cfFetch(
  url: string,
  init: RequestInit,
): Promise<Response> {
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    const response = await fetch(url, init);
    if (response.status !== 429) return response;

    const retryAfter = response.headers.get("Retry-After");
    const parsed = retryAfter ? Number(retryAfter) : NaN;
    const delayMs = Number.isFinite(parsed)
      ? parsed * 1000
      : 1000 * (attempt + 1);
    // Drain the body so the connection can be reused.
    await response.text();
    if (attempt < MAX_RETRIES) {
      await new Promise((r) => setTimeout(r, delayMs));
      continue;
    }
    return response;
  }
  // Unreachable: the loop returns on the final attempt.
  throw new Error(`Cloudflare API request failed: ${url}`);
}

export async function cfApi<T>(
  apiToken: string,
  method: string,
  path: string,
  body?: unknown,
): Promise<T> {
  const token = resolveToken(apiToken);
  const url = `${CF_API_BASE}${path}`;
  const headers: Record<string, string> = {
    "Authorization": `Bearer ${token}`,
    "Content-Type": "application/json",
  };

  const response = await cfFetch(url, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  if (response.status === 429) {
    await response.text();
    throw new Error(
      `Cloudflare API rate limited after ${MAX_RETRIES} retries: ${method} ${path}`,
    );
  }

  if (!response.ok) {
    const text = await response.text();
    throw new Error(
      `Cloudflare API error: ${method} ${path} returned ${response.status} ${response.statusText}: ${
        text.slice(0, 500)
      }`,
    );
  }

  const data = (await response.json()) as CloudflareResponse<T>;

  if (!data.success) {
    const errorMsg = (data.errors ?? []).map((e) => e.message).join("; ") ||
      "Unknown error";
    throw new Error(`Cloudflare API error: ${method} ${path}: ${errorMsg}`);
  }

  return data.result;
}

const MAX_PAGES = 20;

export interface PaginatedResult<T> {
  results: T[];
  truncated: boolean;
  totalFetched: number;
}

export async function cfApiPaginated<T>(
  apiToken: string,
  path: string,
  params?: Record<string, string>,
): Promise<PaginatedResult<T>> {
  const token = resolveToken(apiToken);
  const allResults: T[] = [];
  let page = 1;
  const perPage = 50;
  let truncated = false;

  while (page <= MAX_PAGES) {
    const queryParams = new URLSearchParams({
      ...params,
      page: String(page),
      per_page: String(perPage),
    });

    const url = `${CF_API_BASE}${path}?${queryParams}`;
    const response = await cfFetch(url, {
      headers: {
        "Authorization": `Bearer ${token}`,
      },
    });

    if (response.status === 429) {
      await response.text();
      throw new Error(
        `Cloudflare API rate limited after ${MAX_RETRIES} retries: GET ${path}`,
      );
    }

    if (!response.ok) {
      const text = await response.text();
      throw new Error(
        `Cloudflare API error: GET ${path} returned ${response.status} ${response.statusText}: ${
          text.slice(0, 500)
        }`,
      );
    }

    const data = (await response.json()) as CloudflareResponse<T[]>;

    if (!data.success) {
      const errorMsg = (data.errors ?? []).map((e) => e.message).join("; ") ||
        "Unknown error";
      throw new Error(`Cloudflare API error: GET ${path}: ${errorMsg}`);
    }

    allResults.push(...(data.result ?? []));

    if (data.result_info) {
      if (page >= data.result_info.total_pages) break;
    } else {
      // No result_info: use result count as page-completeness heuristic
      if ((data.result ?? []).length < perPage) break;
      // If we're at MAX_PAGES without result_info, mark truncated
      if (page >= MAX_PAGES) {
        truncated = true;
        break;
      }
    }
    page++;
  }

  if (page > MAX_PAGES) {
    truncated = true;
  }

  return { results: allResults, truncated, totalFetched: allResults.length };
}

/**
 * Follow a Cloudflare cursor-paginated list endpoint's `result_info.cursor`
 * across pages, up to MAX_PAGES, so callers see the full result set (or an
 * honest `truncated: true`) instead of only the first page.
 */
export async function cfApiPaginatedCursor<T>(
  apiToken: string,
  path: string,
  params?: Record<string, string>,
): Promise<PaginatedResult<T>> {
  const token = resolveToken(apiToken);
  const allResults: T[] = [];
  let cursor = params?.cursor;
  let page = 0;
  let truncated = false;

  while (page < MAX_PAGES) {
    const queryParams = new URLSearchParams({
      ...params,
      ...(cursor ? { cursor } : {}),
    });
    const qs = queryParams.toString();
    const url = qs ? `${CF_API_BASE}${path}?${qs}` : `${CF_API_BASE}${path}`;
    const response = await cfFetch(url, {
      headers: {
        "Authorization": `Bearer ${token}`,
      },
    });

    if (response.status === 429) {
      await response.text();
      throw new Error(
        `Cloudflare API rate limited after ${MAX_RETRIES} retries: GET ${path}`,
      );
    }

    if (!response.ok) {
      const text = await response.text();
      throw new Error(
        `Cloudflare API error: GET ${path} returned ${response.status} ${response.statusText}: ${
          text.slice(0, 500)
        }`,
      );
    }

    const data = (await response.json()) as CloudflareResponse<T[]>;

    if (!data.success) {
      const errorMsg = (data.errors ?? []).map((e) => e.message).join("; ") ||
        "Unknown error";
      throw new Error(`Cloudflare API error: GET ${path}: ${errorMsg}`);
    }

    allResults.push(...(data.result ?? []));
    page++;

    if (!data.result_info) {
      // No pagination metadata at all: we cannot confirm this page is the
      // full result set, so don't silently claim completeness.
      truncated = true;
      break;
    }

    const nextCursor = data.result_info.cursor;
    if (!nextCursor) break;
    cursor = nextCursor;
    if (page >= MAX_PAGES) {
      truncated = true;
      break;
    }
  }

  return { results: allResults, truncated, totalFetched: allResults.length };
}
